import ng from "angular";
import { AttendanceVoucher } from "../../models/ui-components/ib-ui-attendance-voucher-card-component/ib-ui-attendance-voucher-card.model";
import { RedirectionService } from "ib-web-commons/utils";
@Component(
  "ib-ui-attendance-voucher-card-module",
  "ibUiAttendanceVoucherCard",
  {
    controllerAs: "uiAttendanceVoucherCardCtrl",
    bindings: {
      attendanceVoucher: "<",
      isPaymentsVoucher: "=",
    },
    templateUrl: [
      "$rootScope",
      ($rootScope: CommonsRootScope) => {
        return `${$rootScope.routes.templates}ib-ui-attendance-voucher-card-view.html`;
      },
    ],
  },
  ["RedirectionService", "$scope"],
  [],
)
class IbUiAttendanceVoucherCard implements ng.IController {
  public attendanceVoucher: AttendanceVoucher;
  public isPaymentsVoucher: boolean;
  constructor(
    private redirectionService: RedirectionService,
    private $scope: ng.IScope,
  ) {}

  getPopoverClass() {
    let className = "";
    if (
      this.attendanceVoucher.typeVoucher === "RESTAURANT" &&
      !this.isPaymentsVoucher
    ) {
      className =
        "ib-attendance-voucher--title-information ib-popover--voucher-mmb-1";
    } else if (
      this.attendanceVoucher.typeVoucher === "RESTAURANT" &&
      this.isPaymentsVoucher
    ) {
      className =
        "ib-attendance-voucher--title-information ib-popover--voucher-payments-1";
    } else if (
      this.attendanceVoucher.typeVoucher === "ACCOMODATION" &&
      !this.isPaymentsVoucher
    ) {
      className =
        "ib-attendance-voucher--title-information-2 ib-popover--voucher-mmb-2";
    } else {
      className =
        "ib-attendance-voucher--title-information-2 ib-popover--voucher-payments-2";
    }
    return className;
  }

  openLink(link: string): void {
    this.redirectionService.newNavigation(link, "_blank");
  }

  sendbyEmail() {
    this.$scope.$emit("sendAttendanceVoucherByEmail");
  }

  downloadPDF() {
    const base64 =
      "";
    const fileName = "AssitanceVoucher";
    const url = this.generatePDFUrl(base64);
    const link = document.createElement("a");
    link.download = `${fileName}`;
    link.href = `${url}`;
    link.click();
    link.remove();
    setTimeout(() => window.URL.revokeObjectURL(url), 1000);
  }

  private generatePDFUrl(base64: string): string {
    const bytes = new Uint8Array(
      [...window.atob(base64)].map((c) => c.charCodeAt(0)),
    );
    const blob = new Blob([bytes], { type: "application/pdf" });
    const url = URL.createObjectURL(blob);
    return url;
  }
}
